from collections import Counter
def split(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    for i in range(1,H-1):
        if len(set(inp[i]))==1 and cnt[inp[i][0]]==W:
            return inp[:i],inp[i+1:],False
    for j in range(1,W-1):
        col={r[j] for r in inp}
        if len(col)==1 and cnt[next(iter(col))]==H:
